import core.models
from django.db import migrations, models

# The twelve seeded products move from drawings to photographs. Only rows still
# pointing at their original drawing are changed, so an image set by hand in the
# admin is left alone. The drawings stay in static/products, so this reverses.
SEEDED_SLUGS = [
    "brass-lamp",
    "canvas-rucksack",
    "cast-iron-pan",
    "enamel-kettle",
    "felt-mousepad",
    "head-torch",
    "linen-apron",
    "linen-notebook",
    "oak-desk-tidy",
    "stoneware-mug",
    "thermos-flask",
    "wool-blanket",
]


def _swap(apps, old_ext: str, new_ext: str) -> None:
    Product = apps.get_model("core", "Product")
    for slug in SEEDED_SLUGS:
        Product.objects.filter(slug=slug, image=f"products/{slug}.{old_ext}").update(
            image=f"products/{slug}.{new_ext}"
        )


def to_photos(apps, schema_editor) -> None:
    _swap(apps, "svg", "jpg")


def to_drawings(apps, schema_editor) -> None:
    _swap(apps, "jpg", "svg")


